"""Plot observed CE only; join aligned stages without adding sibling rounds."""
import pathlib,json,hashlib,csv
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
R=pathlib.Path(__file__).resolve().parents[1];E=R/'execution';C=R.parent/'round28';sha=lambda b:hashlib.sha256(b).hexdigest();oldraw=(C/'continue-10000/metrics.json').read_bytes();newraw=(R/'continue-10000/metrics.json').read_bytes();old=json.loads(oldraw);new=json.loads(newraw)
assert old['history'][-1]['step']==10000 and old['history'][-1]['validation']==new['history'][0]['validation'];rows=[]
for stage,history,offset,tokenoffset,byteoffset in [('round28',old['history'],0,0,0),('round33',new['history'][1:],10000,old['history'][-1]['seenTargetTokens'],old['history'][-1]['seenTargetUtf8Bytes'])]:
 for x in history:rows.append(dict(stage=stage,localActualUpdates=x['step'],actualUpdatesSinceAlignedRound11Latest=offset+x['step'],declaredWeightLineageUpdates=49000+offset+x['step'],optimizerCounter=10000+offset+x['step'],commonDevNllPerUtf8Byte=x['validation']['nllPerUtf8Byte'],cumulativeTargetsSinceAlignedRound11Latest=tokenoffset+x.get('seenTargetTokens',0),cumulativeTargetBytesSinceAlignedRound11Latest=byteoffset+x.get('seenTargetUtf8Bytes',0)))
with (E/'development-trajectory.csv').open('w')as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
fig,ax=plt.subplots(figsize=(9,4.8),layout='constrained');a=[x for x in rows if x['stage']=='round28'];b=[a[-1]]+[x for x in rows if x['stage']=='round33'];ax.plot([x['actualUpdatesSinceAlignedRound11Latest']for x in a],[x['commonDevNllPerUtf8Byte']for x in a],color='#666666',marker='.',label='R28: human conversation mass30%');ax.plot([x['actualUpdatesSinceAlignedRound11Latest']for x in b],[x['commonDevNllPerUtf8Byte']for x in b],color='#1769aa',marker='o',markersize=4,label='R33: same trajectory continued');ax.axvline(10000,color='#999999',linestyle=':',linewidth=1);ax.axhline(.9714220852387883,color='#a35b16',linestyle='--',linewidth=1,label='R25 adopted anchor (different data mixture)');ax.set(xlabel='Actual updates since aligned Round11 latest (R28 + R33)',ylabel='Common exposed DEV CE NLL / UTF-8 byte',title='Observed pretraining trajectory; lower CE is not coherent generation');ax.grid(alpha=.2);ax.legend(fontsize=8);fig.savefig(E/'development-trajectory.svg',metadata={'Date':None});fig.savefig(E/'development-trajectory.png',dpi=150);plt.close(fig)
record=dict(parentMetricsSha256=sha(oldraw),childMetricsSha256=sha(newraw),lastObservedChildValidationStep=new['history'][-1]['step'],observedPoints=len(rows),parentChildZeroValidationExactlyEqual=True,joinedOnlySameAlignedTrajectory=True,noSiblingUpdatesAdded=True,noInterpolatedOrForecastDataValues=True,lineSegmentsAreVisualGuidesOnly=True,meaningImprovementImplied=False,plotCodeSha256=sha(pathlib.Path(__file__).read_bytes()))
(E/'development-trajectory-provenance.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(record))
